const localeCopy: Record<AppLanguage, Record<LocaleCopyKey, string>> = {
  en: { ...baseLocaleCopy.en, configSkip: "Use local chat first" },
  "zh-CN": { ...baseLocaleCopy.en, ...baseLocaleCopy["zh-CN"] },
  "ja-JP": { ...baseLocaleCopy.en, ...localeOverrides["ja-JP"] },
  "ko-KR": { ...baseLocaleCopy.en, ...localeOverrides["ko-KR"] },
  "de-DE": { ...baseLocaleCopy.en, ...localeOverrides["de-DE"] },
  "ru-RU": { ...baseLocaleCopy.en, ...localeOverrides["ru-RU"] },
};

var gbkCopyEncodeMap: Map<string, number[]> | null = null;

const MOJIBAKE_MARKER_PATTERN = /[\u00e6\u00e8\u00e5\u00e3\u00c2\u00c3\ufffd]/;
const GBK_MOJIBAKE_MARKER_PATTERN = /[\u9471\u95b0\u7459\u939b\u93b4\u7481\u7487\u934d\u59af\u93c8\u7015\u9418\u935b\u752f\u95c5\u7f02\u6dc7\u934f\u95c3\u9359\u8930\u9286\ue000-\uf8ff]/;
const READABLE_CHINESE_COPY_TERMS = [
  "\u804a\u5929",
  "\u914d\u7f6e",
  "\u89d2\u8272",
  "\u63d0\u793a\u8bcd",
  "\u623f\u95f4",
  "\u8bb0\u5fc6",
  "\u8bed\u97f3",
  "\u56fe\u7247",
  "\u6a21\u578b",
  "\u672c\u5730",
  "\u5bfc\u6f14",
  "\u72b6\u6001",
  "\u547d\u4ee4",
  "\u5e2e\u52a9",
  "\u9690\u79c1",
  "\u8bca\u65ad",
  "\u521b\u5efa",
  "\u7f16\u8f91",
  "\u5220\u9664",
  "\u4fdd\u5b58",
  "\u516c\u5f00\u9891\u9053",
  "\u9635\u8425\u9891\u9053",
  "\u53d1\u97f3\u63d0\u793a",
  "\u5f53\u524d\u6ca1\u6709\u53ef\u7528\u804a\u5929\u6a21\u578b",
];

function looksLikeMojibakeText(value: string): boolean {
  return MOJIBAKE_MARKER_PATTERN.test(value) || GBK_MOJIBAKE_MARKER_PATTERN.test(value);
}

export function repairMojibakeText(value: string): string {
  if (!value || !looksLikeMojibakeText(value)) {
    return value;
  }

  const candidates = [value, repairLatin1Mojibake(value), repairGbkMojibake(value)];
  let best = value;
  let bestScore = scoreCopyText(value);
  for (const candidate of candidates) {
    const score = scoreCopyText(candidate);
    if (score > bestScore) {
      best = candidate;
      bestScore = score;
    }
  }
  return best;
}

function localizeProductTerms(language: AppLanguage, value: string): string {
  if (language === "en" || !value) {
    return value;
  }
  const terms: Record<Exclude<AppLanguage, "en">, { room: string; rooms: string; director: string }> = {
    "zh-CN": { room: "房间", rooms: "房间", director: "导演" },
    "ja-JP": { room: "ルーム", rooms: "ルーム", director: "ディレクター" },
    "ko-KR": { room: "방", rooms: "방", director: "디렉터" },
    "de-DE": { room: "Raum", rooms: "Raeume", director: "Regie" },
    "ru-RU": { room: "комната", rooms: "комнаты", director: "режиссёр" },
  };
  const placeholders: string[] = [];
  const protectedValue = value.replace(/\{[^}]+\}/g, (placeholder) => {
    placeholders.push(placeholder);
    return `__CASTROOM_PLACEHOLDER_${placeholders.length - 1}__`;
  });
  const localized = protectedValue
    .replace(/\bRooms\b/g, terms[language].rooms)
    .replace(/\brooms\b/g, terms[language].rooms)
    .replace(/\bRoom\b/g, terms[language].room)
    .replace(/\broom\b/g, terms[language].room)
    .replace(/\bDirector\b/g, terms[language].director)
    .replace(/\bdirector\b/g, terms[language].director);
  return localized.replace(/__CASTROOM_PLACEHOLDER_(\d+)__/g, (_, index) => placeholders[Number(index)] ?? "");
}

function normalizeUiCopy(language: AppLanguage, value: string): string {
  return localizeProductTerms(language, repairMojibakeText(value));
}

function repairCopyObject<T extends Record<string, unknown>>(value: T, language: AppLanguage): T {
  const repaired: Record<string, unknown> = {};
  for (const [key, item] of Object.entries(value)) {
    repaired[key] = typeof item === "string" ? normalizeUiCopy(language, item) : item;
  }
  return repaired as T;
}

function repairSetupCopy<T extends { label: string; title: string; rows: string[]; action: string }>(
  value: T,
  language: AppLanguage,
): T {
  return {
    ...value,
    label: normalizeUiCopy(language, value.label),
    title: normalizeUiCopy(language, value.title),
    rows: value.rows.map((row) => normalizeUiCopy(language, row)),
    action: normalizeUiCopy(language, value.action),
  };
}

function repairLatin1Mojibake(value: string): string {
  const bytes: number[] = [];
  for (const char of value) {
    const code = char.codePointAt(0) ?? 0;
    const byte = windows1252ByteFor(char);
    if (byte !== null) {
      bytes.push(byte);
    } else if (code <= 0xff) {
      bytes.push(code);
    } else {
      return value;
    }
  }
  try {
    return new TextDecoder("utf-8", { fatal: true }).decode(new Uint8Array(bytes));
  } catch {
    return value;
  }
}

function repairGbkMojibake(value: string): string {
  const encodeMap = getGbkCopyEncodeMap();
  const bytes: number[] = [];
  for (const char of value) {
    const encoded = encodeMap.get(char);
    if (encoded) {
      bytes.push(...encoded);
      continue;
    }
    const code = char.codePointAt(0) ?? 0;
    if (code <= 0x7f) {
      bytes.push(code);
      continue;
    }
    return value;
  }
  try {
    return new TextDecoder("utf-8", { fatal: true }).decode(new Uint8Array(bytes));
  } catch {
    return value;
  }
}

function getGbkCopyEncodeMap(): Map<string, number[]> {
  if (gbkCopyEncodeMap) {
    return gbkCopyEncodeMap;
  }
  const decoder = new TextDecoder("gbk");
  const map = new Map<string, number[]>();
  for (let first = 0x81; first <= 0xfe; first += 1) {
    for (let second = 0x40; second <= 0xfe; second += 1) {
      if (second === 0x7f) {
        continue;
      }
      const decoded = decoder.decode(new Uint8Array([first, second]));
      if (decoded && decoded.length === 1 && decoded !== "\uFFFD" && !map.has(decoded)) {
        map.set(decoded, [first, second]);
      }
    }
  }
  gbkCopyEncodeMap = map;
  return map;
}

function windows1252ByteFor(char: string): number | null {
  const code = char.codePointAt(0) ?? 0;
  if (code <= 0xff) {
    return code;
  }
  switch (code) {
    case 0x20ac:
      return 0x80;
    case 0x201a:
      return 0x82;
    case 0x0192:
      return 0x83;
    case 0x201e:
      return 0x84;
    case 0x2026:
      return 0x85;
    case 0x2020:
      return 0x86;
    case 0x2021:
      return 0x87;
    case 0x02c6:
      return 0x88;
    case 0x2030:
      return 0x89;
    case 0x0160:
      return 0x8a;
    case 0x2039:
      return 0x8b;
    case 0x0152:
      return 0x8c;
    case 0x017d:
      return 0x8e;
    case 0x2018:
      return 0x91;
    case 0x2019:
      return 0x92;
    case 0x201c:
      return 0x93;
    case 0x201d:
      return 0x94;
    case 0x2022:
      return 0x95;
    case 0x2013:
      return 0x96;
    case 0x2014:
      return 0x97;
    case 0x02dc:
      return 0x98;
    case 0x2122:
      return 0x99;
    case 0x0161:
      return 0x9a;
    case 0x203a:
      return 0x9b;
    case 0x0153:
      return 0x9c;
    case 0x017e:
      return 0x9e;
    case 0x0178:
      return 0x9f;
    default:
      return null;
  }
}

function scoreCopyText(value: string): number {
  let score = 0;
  for (const term of READABLE_CHINESE_COPY_TERMS) {
    if (value.includes(term)) {
      score += term.length * 3;
    }
  }
  const chineseMatches = value.match(/[\p{Script=Han}]/gu);
  score += chineseMatches ? chineseMatches.length : 0;
  const mojibakeMatches = value.match(MOJIBAKE_MARKER_PATTERN);
  if (mojibakeMatches) {
    score -= 40;
  }
  const gbkMojibakeMatches = value.match(GBK_MOJIBAKE_MARKER_PATTERN);
  if (gbkMojibakeMatches) {
    score -= 40;
  }
  const replacementMatches = value.match(/[\uFFFD\u0080-\u009f]/g);
  if (replacementMatches) {
    score -= replacementMatches.length * 8;
  }
  return score;
}

