export function uiText(language: AppLanguage, english: string, zhFallback?: string): string {
  if (language === "en") {
    return english;
  }
  const translated = inlineUiCopy[english]?.[language];
  if (translated) {
    return normalizeUiCopy(language, translated);
  }
  if (language === "zh-CN" && zhFallback) {
    return normalizeUiCopy(language, zhFallback);
  }
  return normalizeUiCopy(language, english);
}

