  "This character package is updated in the project character-pack folder.": { "zh-CN": "这个角色包会在项目角色包目录中直接更新。", "ja-JP": "このキャラクターパックはプロジェクトの character-pack フォルダー内で更新されます。", "ko-KR": "이 캐릭터 패키지는 프로젝트 character-pack 폴더에서 직접 업데이트됩니다.", "de-DE": "Dieses Figurenpaket wird im character-pack-Ordner des Projekts aktualisiert.", "ru-RU": "этот пакет персонажа обновляется в папке character-pack проекта." },
  "This edits the character pack base prompt and affects one-on-one chat plus every room using this character pack.": { "zh-CN": "这里编辑角色包的基础提示词，会影响使用该角色包的一对一聊天和所有房间。", "ja-JP": "キャラクターパックの基本 Prompt を編集します。一対一チャットとこのパックを使うすべての Room に影響します。", "ko-KR": "캐릭터 팩 기본 Prompt를 편집하며 일대일 채팅과 이 캐릭터 팩을 쓰는 모든 Room에 영향을 줍니다.", "de-DE": "Bearbeitet den Basis-Prompt des Figurenpakets und wirkt auf Einzelchat sowie alle Rooms mit dieser Figur.", "ru-RU": "редактирует базовый Prompt пакета персонажа и влияет на чат один на один и все Room с ним." },
  "This is a read-only preview of the compiled Room and Director rules for {mode} mode.": { "zh-CN": "这里只预览 {mode} 模式下已经编译好的房间规则和导演规则，不在这里直接编辑。", "ja-JP": "{mode} モード用にコンパイルされた Room と Director ルールの読み取り専用プレビューです。", "ko-KR": "{mode} 모드의 컴파일된 Room 및 Director 규칙 읽기 전용 미리보기입니다.", "de-DE": "Schreibgeschuetzte Vorschau der kompilierten Room- und Director-Regeln fuer {mode}.", "ru-RU": "просмотр скомпилированных правил Room и Director для режима {mode}; редактирование здесь недоступно." },
