export function normalizeLanguage(value: unknown): AppLanguage {
  return isAppLanguage(value) ? value : "en";
}

export function isAppLanguage(value: unknown): value is AppLanguage {
  return value === "en" || value === "zh-CN" || value === "ja-JP" || value === "ko-KR" || value === "de-DE" || value === "ru-RU";
}

export function languageOptions(currentLanguage: AppLanguage): Array<{ value: AppLanguage; label: string; shortLabel: string; title: string }> {
  const labels: Record<AppLanguage, { label: string; shortLabel: string; selected: string }> = {
    en: { label: "English", shortLabel: "EN", selected: "selected" },
    "zh-CN": { label: "简体中文", shortLabel: "中", selected: "已选择" },
    "ja-JP": { label: "日本語", shortLabel: "日", selected: "選択中" },
    "ko-KR": { label: "한국어", shortLabel: "한", selected: "선택됨" },
    "de-DE": { label: "Deutsch", shortLabel: "DE", selected: "ausgewaehlt" },
    "ru-RU": { label: "Русский", shortLabel: "RU", selected: "выбрано" },
  };
  return (Object.keys(labels) as AppLanguage[]).map((value) => ({
    value,
    label: labels[value].label,
    shortLabel: labels[value].shortLabel,
    title: value === currentLanguage ? `${labels[value].label} · ${labels[value].selected}` : labels[value].label,
  }));
}

