export function localizeEnum(language: AppLanguage, group: keyof typeof enumCopy, value: string, fallback = value): string {
  const localized = enumCopy[group][language] as Record<string, string>;
  const english = enumCopy[group].en as Record<string, string>;
  const supplement = enumCopySupplement[group as keyof typeof enumCopySupplement];
  const localizedSupplement = supplement?.[language] as Record<string, string> | undefined;
  const englishSupplement = supplement?.en as Record<string, string> | undefined;
  return normalizeUiCopy(language, localizedSupplement?.[value] ?? localized[value] ?? englishSupplement?.[value] ?? english[value] ?? fallback);
}

export function formatDateTime(language: AppLanguage, value: Date | string | number, options: Intl.DateTimeFormatOptions = {}): string {
  const date = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(date.getTime())) {
    return "";
  }
  return date.toLocaleString(language, {
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    ...options,
  });
}

