export function categoryLabel(language: AppLanguage, category: CommandDefinition["category"]): string {
  const labels: Record<AppLanguage, Record<CommandDefinition["category"], string>> = {
    en: { help: "Help", ai: "AI", debug: "Debug" },
    "zh-CN": { help: "帮助", ai: "AI", debug: "调试" },
    "ja-JP": { help: "ヘルプ", ai: "AI", debug: "デバッグ" },
    "ko-KR": { help: "도움말", ai: "AI", debug: "디버그" },
    "de-DE": { help: "Hilfe", ai: "AI", debug: "Debug" },
    "ru-RU": { help: "Помощь", ai: "AI", debug: "Отладка" },
  };
  return labels[language]?.[category] ?? labels.en[category];
}

export function connectionLabel(language: AppLanguage, status: AiConnectionStatus): string {
  const labels: Record<AppLanguage, Record<AiConnectionStatus, string>> = {
    en: { not_configured: "not configured", ready: "ready", testing: "testing", error: "error" },
    "zh-CN": { not_configured: "未配置", ready: "可用", testing: "测试中", error: "错误" },
    "ja-JP": { not_configured: "未設定", ready: "利用可能", testing: "テスト中", error: "エラー" },
    "ko-KR": { not_configured: "미설정", ready: "사용 가능", testing: "테스트 중", error: "오류" },
    "de-DE": { not_configured: "nicht konfiguriert", ready: "bereit", testing: "Test laeuft", error: "Fehler" },
    "ru-RU": { not_configured: "не настроено", ready: "готово", testing: "проверка", error: "ошибка" },
  };
  return labels[language]?.[status] ?? labels.en[status];
}
